def get_index_html(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0096000" if __import__("os").path.isdir("./environment_mix/0096000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _ensure_audit_collections():
        # Create minimal observable dynamics collections if absent.
        # These files are not part of the schema, but are required for traffic observability.
        usage_path = os.path.join(_DB, "_usage.json")
        quota_path = os.path.join(_DB, "_quota.json")
        if not os.path.exists(usage_path):
            _save("_usage.json", [])
        if not os.path.exists(quota_path):
            _save(
                "_quota.json",
                {
                    "rate_limit_per_minute": 120,
                    "daily_quota": 5000,
                    "counters": {"total_requests": 0, "total_errors": 0},
                },
            )

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_enforce(endpoint, status="ok", latency_ms=None, error_code=None):
        _ensure_audit_collections()
        quota = _load("_quota.json")
        if not isinstance(quota, dict):
            quota = {"rate_limit_per_minute": 120, "daily_quota": 5000, "counters": {"total_requests": 0, "total_errors": 0}}

        usage = _load("_usage.json")
        if not isinstance(usage, list):
            usage = []

        now = datetime.datetime.utcnow()
        day_key = now.strftime("%Y-%m-%d")
        minute_ago = now - datetime.timedelta(seconds=60)

        # Rate limit: count requests in last 60s
        recent = 0
        today = 0
        for r in usage:
            if not isinstance(r, dict):
                continue
            ts = r.get("ts")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= minute_ago:
                recent += 1
            if ts.startswith(day_key):
                today += 1

        rlim = quota.get("rate_limit_per_minute", 120)
        dlim = quota.get("daily_quota", 5000)
        if not isinstance(rlim, int) or rlim < 1:
            rlim = 120
        if not isinstance(dlim, int) or dlim < 1:
            dlim = 5000

        if recent >= rlim:
            # still log the refused request
            usage.append(
                {
                    "id": (usage[-1]["id"] + 1) if usage and isinstance(usage[-1], dict) and isinstance(usage[-1].get("id"), int) else 1,
                    "ts": _now_iso(),
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "RATE_LIMIT",
                    "latency_ms": latency_ms,
                }
            )
            quota.setdefault("counters", {})
            quota["counters"]["total_requests"] = int(quota["counters"].get("total_requests", 0) or 0) + 1
            quota["counters"]["total_errors"] = int(quota["counters"].get("total_errors", 0) or 0) + 1
            _save("_usage.json", usage)
            _save("_quota.json", quota)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")

        if today >= dlim:
            usage.append(
                {
                    "id": (usage[-1]["id"] + 1) if usage and isinstance(usage[-1], dict) and isinstance(usage[-1].get("id"), int) else 1,
                    "ts": _now_iso(),
                    "endpoint": endpoint,
                    "status": "error",
                    "error_code": "QUOTA_EXCEEDED",
                    "latency_ms": latency_ms,
                }
            )
            quota.setdefault("counters", {})
            quota["counters"]["total_requests"] = int(quota["counters"].get("total_requests", 0) or 0) + 1
            quota["counters"]["total_errors"] = int(quota["counters"].get("total_errors", 0) or 0) + 1
            _save("_usage.json", usage)
            _save("_quota.json", quota)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded. Please retry tomorrow.")

        # allowed; append the record
        usage.append(
            {
                "id": (usage[-1]["id"] + 1) if usage and isinstance(usage[-1], dict) and isinstance(usage[-1].get("id"), int) else 1,
                "ts": _now_iso(),
                "endpoint": endpoint,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
            }
        )
        quota.setdefault("counters", {})
        quota["counters"]["total_requests"] = int(quota["counters"].get("total_requests", 0) or 0) + 1
        if status != "ok":
            quota["counters"]["total_errors"] = int(quota["counters"].get("total_errors", 0) or 0) + 1
        _save("_usage.json", usage)
        _save("_quota.json", quota)
        return None

    t0 = time.time()
    # Enforce quota/rate limit first (but log refusal too).
    pre = _log_and_enforce("get_index_html", status="ok", latency_ms=None)
    if isinstance(pre, dict) and pre.get("error"):
        return pre

    # Serve index from web root; do not raise on missing.
    candidates = [
        os.path.join(_DB, "web_pages", "index.html"),
        os.path.join(_DB, "index.html"),
    ]
    content = None
    last_err = None
    for p in candidates:
        try:
            with open(p, encoding="utf-8") as f:
                content = f.read()
                break
        except FileNotFoundError as e:
            last_err = e
        except PermissionError as e:
            last_err = e

    latency = int((time.time() - t0) * 1000)
    if content is None:
        _log_and_enforce("get_index_html", status="error", latency_ms=latency, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Index document not found or not readable.")

    _log_and_enforce("get_index_html", status="ok", latency_ms=latency)
    return {"html": content}

