    t0 = time.time()
    pre = _log_and_enforce("get_posts_json", status="ok", latency_ms=None)
    if isinstance(pre, dict) and pre.get("error"):
        return pre

    # Real datastore posts live in /app/database/posts.json (schema)
    path = os.path.join(_DB, "posts.json")
    try:
        with open(path, encoding="utf-8") as f:
            parsed = json.load(f)
    except FileNotFoundError:
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Posts collection not found.")
    except json.JSONDecodeError:
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Posts collection is not valid JSON.")

    # Accept either raw array or {"rows":[...]} shaped file; refuse others.
    if isinstance(parsed, list):
        rows = parsed
    elif isinstance(parsed, dict) and isinstance(parsed.get("rows"), list):
        rows = parsed["rows"]
    else:
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Posts collection JSON is not in the expected array form.")

    # Validate row shapes minimally (do not fail on extra fields; do fail on wrong types/enums)
    allowed_authors = {"alice", "bob", "carol", "david", "eve"}
    for i, r in enumerate(rows):
        if not isinstance(r, dict):
            latency = int((time.time() - t0) * 1000)
            _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Posts collection contains a non-object row.", index=i)
        if "id" in r and not isinstance(r["id"], int):
            latency = int((time.time() - t0) * 1000)
            _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Post.id must be an integer.", index=i)
        if "title" in r and not isinstance(r["title"], str):
            latency = int((time.time() - t0) * 1000)
            _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Post.title must be a string.", index=i)
        if "author" in r:
            if not isinstance(r["author"], str) or r["author"] not in allowed_authors:
                latency = int((time.time() - t0) * 1000)
                _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Post.author must be one of the allowed authors.", index=i, allowed=sorted(list(allowed_authors)))
        if "body" in r and not isinstance(r["body"], str):
            latency = int((time.time() - t0) * 1000)
            _log_and_enforce("get_posts_json", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Post.body must be a string.", index=i)

    latency = int((time.time() - t0) * 1000)
    _log_and_enforce("get_posts_json", status="ok", latency_ms=latency)
    return {"posts": rows, "count": len(rows)}

