    if prefix is not None and not isinstance(prefix, str):
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("list_static_files", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prefix must be a string when provided.")

    root = os.path.abspath(_DB)
    rel_prefix = prefix or ""
    # Normalize and validate relative path constraints (no absolute, no traversal outside root)
    if rel_prefix.startswith(("/", "\\")) or (len(rel_prefix) >= 2 and rel_prefix[1] == ":" and rel_prefix[0].isalpha()):
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("list_static_files", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prefix must be a relative path.")

    norm_rel = os.path.normpath(rel_prefix)
    if norm_rel == ".":
        norm_rel = ""
    # Reject traversal patterns
    parts = [p for p in norm_rel.replace("\\", "/").split("/") if p not in ("", ".")]
    if any(p == ".." for p in parts):
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("list_static_files", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prefix must not traverse outside the web root.")

    base = os.path.abspath(os.path.join(root, norm_rel))
    # Ensure within root
    if not (base == root or base.startswith(root + os.sep)):
        latency = int((time.time() - t0) * 1000)
        _log_and_enforce("list_static_files", status="error", latency_ms=latency, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prefix must resolve under the web root.")

    # It refuses requests when the prefix does not resolve to an accessible location under web root.
    # We treat "accessible location" as an existing directory or file path.
    if norm_rel != "":
        if not os.path.exists(base):
            latency = int((time.time() - t0) * 1000)
            _log_and_enforce("list_static_files", status="error", latency_ms=latency, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "prefix does not resolve to an accessible location under the web root.")
        # If it's a file, list just that file.
        if os.path.isfile(base):
            relp = os.path.relpath(base, root).replace("\\", "/")
            latency = int((time.time() - t0) * 1000)
            _log_and_enforce("list_static_files", status="ok", latency_ms=latency)
            return {"files": [relp], "count": 1, "prefix": rel_prefix}

    out = []
    # Walk from base (which is root if empty prefix)
    for dp, dn, fn in os.walk(base):
        for f in fn:
            full = os.path.join(dp, f)
            rel = os.path.relpath(full, root).replace("\\", "/")
            # If caller provided a prefix, ensure the returned relative path starts with it (as provided semantics)
            if rel_prefix:
                # Use forward-slash normalized comparison
                want = rel_prefix.replace("\\", "/")
                if not rel.startswith(want.rstrip("/") + "/") and rel != want:
                    continue
            out.append(rel)

    out = sorted(set(out))
    latency = int((time.time() - t0) * 1000)
    _log_and_enforce("list_static_files", status="ok", latency_ms=latency)
    return {"files": out, "count": len(out), "prefix": rel_prefix}
